() => {
  // Get the full HTML structure of the header nav area
  const nav = document.querySelector('nav');
  const headerUserInfo = document.querySelector('.header_user_info');

  // Find all login/logout related links
  const loginLinks = document.querySelectorAll('a.login');
  const logoutLinks = document.querySelectorAll('a.logout');

  return {
    navHTML: nav ? nav.outerHTML.substring(0, 500) : 'not found',
    headerUserInfoHTML: headerUserInfo ? headerUserInfo.outerHTML : 'not found',
    loginLinksCount: loginLinks.length,
    logoutLinksCount: logoutLinks.length,
    loginLinksInfo: Array.from(loginLinks).map(l => ({class: l.className, parent: l.parentElement?.className})),
    // Check if header_user_info is a child of nav or separate
    headerUserInfoParent: headerUserInfo ? headerUserInfo.parentElement?.className : 'not found'
  };
}

